    def __init__(self, transport: AsyncHttpTransport) -> None:
        self._transport = transport

    async def __call__(self, name: str, **params: Any) -> Any:
        return await self._call(name, _prefixed(params))

    async def _call(self, name: str, body: Dict[str, Any]) -> Any:
        return await self._transport.post(f"/api/db/rpc/{name}", json_body=body)

    async def advance_agent_workflow(
        self,
        *,
        workflow_id: str,
        expected_revision: int,
    ) -> Union["AgentWorkflowsRow", List["AgentWorkflowsRow"]]:
        """
        Advance a workflow after its current proposal settles

        Observes the current AUTO-04 proposal at the expected workflow revision. A succeeded proposal advances to the next pinned step; rejection, failure or cancellation pauses the workflow. It never approves or executes a proposal.

        Scopes: agent_operations:write.

        ``POST /api/db/rpc/advance_agent_workflow``
        """
        body: Dict[str, Any] = {}
        body["p_workflow_id"] = workflow_id
        body["p_expected_revision"] = expected_revision
        return await self._call("advance_agent_workflow", body)  # type: ignore[no-any-return]

