        body["p_budget"] = budget
        body["p_initial_usage"] = initial_usage
        body["p_provenance"] = provenance
        body["p_idempotency_key"] = idempotency_key
        return await self._call("create_agent_workflow", body)  # type: ignore[no-any-return]

