    async def create_webhook_subscription(
        self,
        *,
        workspace_id: str,
        key: str,
        url: Union[str, Unset] = UNSET,
        channel_type: Union[str, Unset] = UNSET,
        recipient_user_id: Union[str, Unset] = UNSET,
        event_types: Union[List["JsonValue"], Unset] = UNSET,
        description: Union[str, Unset] = UNSET,
        max_retries: Union[int, Unset] = UNSET,
        failure_threshold: Union[int, Unset] = UNSET,
        signing_secret: Union[str, Unset] = UNSET,
        rate_limit_per_minute: Union[int, Unset] = UNSET,
    ) -> "WebhookSubscriptionResult":
        """
        Create a webhook subscription

        Creates a subscription in the JWT workspace. Returns the subscription row and, for a webhook or Teams destination, a generated signing secret (returned exactly once). An email destination names a recipient instead of a URL and gets no secret. rate_limit_per_minute caps delivery attempts per rolling minute (deferred, never dropped); null = unlimited.

        Scopes: webhooks:write.

        ``POST /api/db/rpc/create_webhook_subscription``
        """
        body: Dict[str, Any] = {}
        body["p_workspace_id"] = workspace_id
        body["p_key"] = key
        if not isinstance(url, Unset):
            body["p_url"] = url
        if not isinstance(channel_type, Unset):
            body["p_channel_type"] = channel_type
        if not isinstance(recipient_user_id, Unset):
            body["p_recipient_user_id"] = recipient_user_id
        if not isinstance(event_types, Unset):
            body["p_event_types"] = event_types
        if not isinstance(description, Unset):
            body["p_description"] = description
        if not isinstance(max_retries, Unset):
            body["p_max_retries"] = max_retries
        if not isinstance(failure_threshold, Unset):
            body["p_failure_threshold"] = failure_threshold
        if not isinstance(signing_secret, Unset):
            body["p_signing_secret"] = signing_secret
        if not isinstance(rate_limit_per_minute, Unset):
            body["p_rate_limit_per_minute"] = rate_limit_per_minute
        return await self._call("create_webhook_subscription", body)  # type: ignore[no-any-return]

