    async def replay_webhook_deliveries(
        self,
        *,
        workspace_id: str,
        subscription_id: Union[str, Unset] = UNSET,
        since: Union[str, Unset] = UNSET,
        until: Union[str, Unset] = UNSET,
        status: Union[str, Unset] = UNSET,
        limit: Union[int, Unset] = UNSET,
    ) -> "WebhookBulkReplayResult":
        """
        Replay webhook deliveries by subscription and/or time window

        Operator-invoked bulk replay of terminal deliveries (default dead_letter) for a subscription and/or creation window. Each replay reuses the original idempotency key. Originals with a pending/retrying replay already queued are skipped, so re-running a window is safe. One summary change event audits the action; never automatic.

        Scopes: webhooks:write.

        ``POST /api/db/rpc/replay_webhook_deliveries``
        """
        body: Dict[str, Any] = {}
        body["p_workspace_id"] = workspace_id
        if not isinstance(subscription_id, Unset):
            body["p_subscription_id"] = subscription_id
        if not isinstance(since, Unset):
            body["p_since"] = since
        if not isinstance(until, Unset):
            body["p_until"] = until
        if not isinstance(status, Unset):
            body["p_status"] = status
        if not isinstance(limit, Unset):
            body["p_limit"] = limit
        return await self._call("replay_webhook_deliveries", body)  # type: ignore[no-any-return]

    async def replay_webhook_delivery(
        self,
        *,
        workspace_id: str,
        delivery_id: str,
    ) -> Union["WebhookDeliveriesRow", List["WebhookDeliveriesRow"]]:
        """
        Replay a webhook delivery

        Creates a new pending delivery from an existing terminal one (delivered, failed, dead_letter), reusing the original payload, body, and signature — the same idempotency key, so receivers that deduplicate never see a duplicate effect. Audited via replay lineage plus a change event.

        Scopes: webhooks:write.

        ``POST /api/db/rpc/replay_webhook_delivery``
        """
        body: Dict[str, Any] = {}
        body["p_workspace_id"] = workspace_id
        body["p_delivery_id"] = delivery_id
        return await self._call("replay_webhook_delivery", body)  # type: ignore[no-any-return]

